#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAzaClient: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = AzaClient

    public static func lift(_ handle: UInt64) throws -> AzaClient {
        return AzaClient(unsafeFromHandle: handle)
    }

    public static func lower(_ value: AzaClient) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AzaClient {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: AzaClient, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeAzaClient_lift(_ handle: UInt64) throws -> AzaClient {
    return try FfiConverterTypeAzaClient.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeAzaClient_lower(_ value: AzaClient) -> UInt64 {
    return FfiConverterTypeAzaClient.lower(value)
}






/**
 * The aza app's side: one device of one identity.
 */
public protocol AzaDeviceProtocol: AnyObject, Sendable {
    
    func acceptContactRequest(item: String) async throws 
    
    func approvals() async throws  -> [ApprovalInfo]
    
    /**
     * Approves a new device from its pairing QR code; returns its device ID.
     */
    func approvePairing(qr: String) async throws  -> String
    
    /**
     * Approves a request shown as a QR code on another machine.
     */
    func approveQr(qr: String) async throws 
    
    /**
     * Approves `aza:approve#req=…`; returns the app's return URL with the certificate, to open.
     */
    func approveUrl(url: String) async throws  -> String
    
    /**
     * The master's keys as a password-protected backup file.
     */
    func backupMaster(password: String) async throws  -> Data
    
    /**
     * The master's next key as a separate backup file.
     */
    func backupNext(password: String) async throws  -> Data
    
    func contactRequests() async throws  -> [ContactRequestInfo]
    
    /**
     * The app and scopes a request shown as a QR code on another machine asks for, to show
     * before approving.
     */
    func describeQr(qr: String) async throws  -> ApprovalInfo
    
    /**
     * The app and scopes an `aza:approve#req=…` asks for, to show before approving.
     */
    func describeRequest(url: String) throws  -> ApprovalInfo
    
    func deviceId() async  -> String
    
    func devices() async  -> [DeviceInfo]
    
    /**
     * Deletes the master's keys from this machine, once both backups are saved.
     */
    func forgetMaster() async 
    
    func holdsMaster() async  -> Bool
    
    func identity() async  -> String
    
    /**
     * Opens the master's backup file for this session, to make repairs.
     */
    func openMaster(file: Data, password: String) async throws 
    
    /**
     * The profile picture's image, checked against its hash.
     */
    func picture() async throws  -> Data?
    
    func profile() async throws  -> ProfileInfo
    
    func refresh() async throws 
    
    /**
     * Removes a device for good with the master, keeping its changes up to `keep`.
     */
    func removeDevice(device: String, keep: String?) async throws 
    
    func revokeClient(client: String) async throws 
    
    func save() async  -> Data
    
    func setHandle(handle: String?) async throws 
    
    func setName(name: String) async throws 
    
    func setPicture(image: Data, imageType: String) async throws 
    
    /**
     * Signs out a device, endorsing every post made through its approvals.
     */
    func signOut(device: String) async throws 
    
}
/**
 * The aza app's side: one device of one identity.
 */
open class AzaDevice: AzaDeviceProtocol, @unchecked Sendable {
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noHandle: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing handle the FFI lower functions will crash.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public init(noHandle: NoHandle) {
        self.handle = 0
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public func uniffiCloneHandle() -> UInt64 {
        return try! rustCall { uniffi_aza_kit_fn_clone_azadevice(self.handle, $0) }
    }
    // No primary constructor declared for this class.

    deinit {
        if handle == 0 {
            // Mock objects have handle=0 don't try to free them
            return
        }

        try! rustCall { uniffi_aza_kit_fn_free_azadevice(handle, $0) }
    }

    
    /**
     * Creates an identity on `node` with a device for this machine called `label`. The master
     * and its next key stay in this session until `backup_master`, `backup_next` and
     * `forget_master`.
