public 
enum AzaError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case Malformed(message: String
    )
    case Refused(message: String
    )
    case NotFound(message: String
    )
    /**
     * Someone else wrote first: read again, merge, and write the next version.
     */
    case Conflict(message: String
    )
    case Node(status: UInt16, message: String
    )
    case Network(message: String
    )
    case BadPassword
    case Unreadable
    case NoIdentity

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension AzaError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAzaError: FfiConverterRustBuffer {
    typealias SwiftType = AzaError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AzaError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Malformed(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Refused(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .NotFound(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Conflict(
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Node(
            status: try FfiConverterUInt16.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Network(
            message: try FfiConverterString.read(from: &buf)
            )
        case 7: return .BadPassword
        case 8: return .Unreadable
        case 9: return .NoIdentity

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AzaError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Malformed(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Refused(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .NotFound(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Conflict(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Node(status,message):
            writeInt(&buf, Int32(5))
            FfiConverterUInt16.write(status, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Network(message):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(message, into: &buf)
            
        
        case .BadPassword:
            writeInt(&buf, Int32(7))
        
        
        case .Unreadable:
            writeInt(&buf, Int32(8))
        
        
        case .NoIdentity:
            writeInt(&buf, Int32(9))
        
        }
    }
}


